<?php
require __DIR__.'/app/bootstrap.php';$pdo=db();$service=new VacationBreakService($pdo);$id=(int)($_GET['id']??$_POST['id']??0);$break=$service->one($id);if(!$break){http_response_code(404);exit('Vacation Break not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){$userId=require_auth();verify_csrf();$r=$service->complete($userId,$break);flash('success','Break completed. +'.$r['points'].' Vacation Brain points.');redirect('vacation-break.php?id='.$id);}
$success=flash('success');$title=$break['title'].' — Vacation Brain';require __DIR__.'/partials/header.php';
?>
<section class="break-experience"><div class="shell break-shell"><div class="break-orb"><span>VACATION BREAK</span><strong><?=max(1,(int)round($break['duration_seconds']/60))?>:00</strong></div><div class="eyebrow">Do not disturb your imaginary vacation</div><h1><?=e($break['title'])?></h1><p class="break-copy"><?=e($break['body'])?></p><?php if($break['activity_text']):?><div class="break-action"><?=nl2br(e($break['activity_text']))?></div><?php endif;?><?php if($break['ending_text']):?><p class="muted"><?=e($break['ending_text'])?></p><?php endif;?><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><div class="share-row"><?php if(auth_user_id()):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><button class="button primary">I took the break</button></form><?php else:?><a class="button primary" href="<?=e(app_url('login.php'))?>">Sign in to count this break</a><?php endif;?><a class="button secondary" href="<?=e(app_url('breaks.php'))?>">Another escape</a></div></div></section><?php require __DIR__.'/partials/footer.php';?>
